import type {
  ComboboxCollection,
  ComboboxOptionItem,
  ComboboxRootProps,
  ComboboxTriggerProps,
} from '@designharness/primitives';
import { Combobox as ComboboxPrimitive } from '@designharness/primitives';
import type { ComponentPropsWithRef, CSSProperties, ReactNode } from 'react';
import { cx, element, modifier } from './internal/classnames.js';

/**
 * Styled `Combobox`, async-search friendly.
 *
 * Keyboard behaviour and every ARIA attribute (`role="combobox"` on the input,
 * `aria-expanded`, `aria-controls`, `aria-activedescendant`, the `role="listbox"`
 * surface and the `role="option"` items) are owned by the `@zag-js/combobox` machine
 * behind the primitive. This layer contributes classes, the disclosure/clear glyphs and
 * the loading + empty rows the machine has no markup for.
 */

/** Block class for every combobox selector in `styles/combobox.css`. */
export const COMBOBOX_BLOCK = 'dh-combobox';

/** Props of the faithful styled `combobox` anatomy root (same names as the primitive). */
export type UIComboboxRootProps<T extends ComboboxOptionItem> = ComboboxRootProps<T> & {
  className?: string | undefined;
};

/** Anatomy root: context provider only, exactly like `Combobox.Root` in the primitives. */
export function ComboboxRoot<T extends ComboboxOptionItem>(props: UIComboboxRootProps<T>): ReactNode {
  const { className, style, children, ...restProps } = props;
  return (
    <ComboboxPrimitive.Root
      {...restProps}
      className={cx(COMBOBOX_BLOCK, className)}
      style={style}
    >
      {children}
    </ComboboxPrimitive.Root>
  );
}

export type UIComboboxProps<T extends ComboboxOptionItem> = Omit<
  ComboboxRootProps<T>,
  'children' | 'items' | 'collection' | 'filter' | 'className' | 'style'
> & {
  /** Option list. For async sources, hand in the current page of results. */
  items?: readonly T[] | undefined;
  /** Pre-built collection (grouped or server-driven); takes precedence over `items`. */
  collection?: ComboboxCollection<T> | undefined;
  /**
   * Local predicate over `items`. Async consumers that already filtered server-side
   * should pass `() => true` so nothing is hidden twice.
   */
  filter?: ((item: T, query: string) => boolean) | undefined;
  /** Visible label. A combobox without a label is a DESIGN.md prohibition. */
  label?: ReactNode | undefined;
  /** Render the clear button when a value is selected. @default true */
  clearable?: boolean | undefined;
  /** Async request in flight: shows the loading row and spins the disclosure glyph. */
  loading?: boolean | undefined;
  /** Copy for the loading row. @default "Searching…" */
  loadingText?: ReactNode | undefined;
  /** Copy for the no-match row. @default "No matches found" */
  emptyText?: ReactNode | undefined;
  /** Custom option content; defaults to `item.label`. */
  renderOption?: ((item: T) => ReactNode) | undefined;
  className?: string | undefined;
  style?: CSSProperties | undefined;
  children?: ReactNode | undefined;
};

export type UIComboboxTriggerProps = ComboboxTriggerProps & {
  /** Spin the disclosure glyph in place of the chevron. */
  loading?: boolean | undefined;
};

/** Native button props accepted by the clear trigger (the machine owns `type`). */
export type UIComboboxClearProps = Omit<ComponentPropsWithRef<'button'>, 'type'>;

/** Disclosure trigger with the styled layer's glyph. `aria-expanded` stays machine-owned. */
export function ComboboxTrigger(props: UIComboboxTriggerProps): ReactNode {
  const { children, className, loading = false, ...restProps } = props;
  return (
    <ComboboxPrimitive.Trigger {...restProps} className={cx(element(COMBOBOX_BLOCK, 'trigger'), className)}>
      {children ??
        (loading ? (
          <span className={element(COMBOBOX_BLOCK, 'spinner')} aria-hidden="true" />
        ) : (
          <span className={element(COMBOBOX_BLOCK, 'chevron')} aria-hidden="true" />
        ))}
    </ComboboxPrimitive.Trigger>
  );
}

/** Clear button with the styled layer's glyph. Its accessible name comes from the machine. */
export function ComboboxClear(props: UIComboboxClearProps): ReactNode {
  const { children, className, ...restProps } = props;
  return (
    <ComboboxPrimitive.Clear {...restProps} className={cx(element(COMBOBOX_BLOCK, 'clear'), className)}>
      {children ?? <span className={element(COMBOBOX_BLOCK, 'clear-glyph')} aria-hidden="true">×</span>}
    </ComboboxPrimitive.Clear>
  );
}

/**
 * The whole field: label, control (input + trigger + clear) and the floating listbox.
 * Controlled and uncontrolled props keep the primitive's names (`value`/`defaultValue`,
 * `inputValue`/`defaultInputValue`, `open`/`defaultOpen`, `onValueChange`,
 * `onInputValueChange`, `onOpenChange`).
 */
export function UICombobox<T extends ComboboxOptionItem>(props: UIComboboxProps<T>): ReactNode {
  const {
    items,
    collection,
    filter,
    label,
    clearable = true,
    loading = false,
    loadingText = 'Searching…',
    emptyText = 'No matches found',
    renderOption,
    className,
    style,
    children,
    ...restProps
  } = props;

  return (
    <ComboboxRoot
      {...restProps}
      items={items}
      collection={collection}
      filter={filter}
      className={cx(loading ? modifier(COMBOBOX_BLOCK, 'loading') : undefined, className)}
      style={style}
    >
      {(state) => (
        <>
          {label !== undefined && label !== null ? <ComboboxPrimitive.Label>{label}</ComboboxPrimitive.Label> : null}
          <ComboboxPrimitive.Control>
            <ComboboxPrimitive.Input />
            <ComboboxTrigger loading={loading} />
            {clearable && state.value.length > 0 ? <ComboboxClear /> : null}
          </ComboboxPrimitive.Control>
          <ComboboxPrimitive.Positioner>
            <ComboboxPrimitive.Content>
              {loading ? (
                /**
                 * A `role="listbox"` must own at least one `role="option"` (WCAG 2.2 SC 1.3.1 /
                 * 4.1.2, which axe-core enforces as `aria-required-children` + `aria-required-parent`).
                 * "Searching…" is therefore an owned but `aria-disabled` option — the APG-compatible way
                 * to say "this list has nothing you can take yet" without breaking the pattern, and the
                 * machine never highlights or commits it.
                 */
                <div className={element(COMBOBOX_BLOCK, 'loading')} role="option" aria-selected="false" aria-disabled="true">
                  {loadingText}
                </div>
              ) : null}
              <ComboboxPrimitive.List>
                {(listItems) =>
                  listItems.length === 0 ? (
                    <li className={element(COMBOBOX_BLOCK, 'empty')} role="option" aria-selected="false" aria-disabled="true">
                      {emptyText}
                    </li>
                  ) : (
                    listItems.map((item) => (
                      // The machine's filtered list holds the very objects handed in through
                      // `items: readonly T[]`, so re-widening to `T` is identity-preserving.
                      <ComboboxPrimitive.Option key={item.value} item={item as T}>
                        {renderOption !== undefined ? renderOption(item as T) : item.label}
                      </ComboboxPrimitive.Option>
                    ))
                  )
                }
              </ComboboxPrimitive.List>
            </ComboboxPrimitive.Content>
          </ComboboxPrimitive.Positioner>
          {children}
        </>
      )}
    </ComboboxRoot>
  );
}

/** Callable async combobox plus the frozen compound parts. */
export interface ComboboxComponent {
  <T extends ComboboxOptionItem>(props: UIComboboxProps<T>): ReactNode;
  Root: typeof ComboboxRoot;
  Label: typeof ComboboxPrimitive.Label;
  Control: typeof ComboboxPrimitive.Control;
  Input: typeof ComboboxPrimitive.Input;
  Trigger: typeof ComboboxTrigger;
  Clear: typeof ComboboxClear;
  Positioner: typeof ComboboxPrimitive.Positioner;
  Content: typeof ComboboxPrimitive.Content;
  List: typeof ComboboxPrimitive.List;
  Option: typeof ComboboxPrimitive.Option;
}

export const Combobox: ComboboxComponent = Object.assign(UICombobox, {
  Root: ComboboxRoot,
  Label: ComboboxPrimitive.Label,
  Control: ComboboxPrimitive.Control,
  Input: ComboboxPrimitive.Input,
  Trigger: ComboboxTrigger,
  Clear: ComboboxClear,
  Positioner: ComboboxPrimitive.Positioner,
  Content: ComboboxPrimitive.Content,
  List: ComboboxPrimitive.List,
  Option: ComboboxPrimitive.Option,
});

/*
 * Combobox — styling for the frozen `combobox` anatomy: `root`, `label`, `control`,
 * `trigger`, `input`, `clear`, `positioner`, `content`, `list`, `option` (kebab-cased
 * `data-part` values), plus the glyph/loading/empty elements this layer renders.
 *
 * The `@zag-js/combobox` machine supplies the inline positioning styles on the
 * positioner, so nothing here sets `position` or `inset` for the floating surface.
 */

@layer components {
  [data-part="root"]:where([data-scope="combobox"]) {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--space-xxs);
    box-sizing: border-box;
    inline-size: 100%;
    font-family: var(--font-family-body);
    color: var(--color-text-primary);
  }

  /* `label-caps` again for the field label — same reserved uppercase style as `input`. */
  [data-part="label"]:where([data-scope="combobox"]) {
    font-size: var(--font-size-label-caps);
    font-weight: var(--font-weight-label-caps);
    line-height: var(--line-height-label-caps);
    letter-spacing: var(--letter-spacing-label-caps);
    text-transform: uppercase;
    color: var(--color-text-secondary);
  }

  /* --- the field box ------------------------------------------------------------ */

  [data-part="control"]:where([data-scope="combobox"]) {
    display: flex;
    align-items: center;
    gap: var(--space-xxs);
    box-sizing: border-box;
    min-block-size: var(--input-height);
    padding-inline-start: var(--input-padding-inline);
    border-width: var(--border-width-hairline);
    border-style: solid;
    border-color: var(--color-border-strong);
    border-radius: var(--radius-sm);
    background-color: var(--color-surface);
    transition:
      border-color var(--duration-fast) var(--easing-standard),
      background-color var(--duration-fast) var(--easing-standard);
  }

  [data-part="control"]:where([data-scope="combobox"]):hover {
    background-color: var(--color-surface-sunken);
  }

  /* The disclosure seam is the open cue; the listbox surface is the second signal. */
  [data-part="control"][data-open]:where([data-scope="combobox"]) {
    border-color: var(--color-border-selected);
  }

  [data-part="control"][data-disabled]:where([data-scope="combobox"]) {
    background-color: var(--color-surface-sunken);
    border-color: var(--color-border-subtle);
    cursor: default;
    opacity: 0.55;
  }

  /* Async in flight: a dashed seam reads as "waiting", never as an error. */
  .dh-combobox--loading [data-part="control"] {
    border-style: dashed;
  }

  [data-part="input"]:where([data-scope="combobox"]) {
    flex: 1;
    box-sizing: border-box;
    min-inline-size: 0;
    block-size: 100%;
    padding-block: var(--space-xxs);
    padding-inline-end: var(--space-xxs);
    border: none;
    background-color: transparent;
    color: var(--color-text-primary);
    font-family: inherit;
    font-size: var(--font-size-body-md);
    line-height: var(--line-height-body-md);
  }

  [data-part="input"]:where([data-scope="combobox"])::placeholder {
    color: var(--color-text-secondary);
    opacity: 1;
  }

  [data-part="input"][data-invalid]:where([data-scope="combobox"]) {
    color: var(--color-danger);
    font-weight: var(--font-weight-label-caps);
  }

  /* --- buttons inside the field -------------------------------------------------- */

  .dh-combobox__trigger,
  .dh-combobox__clear {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    box-sizing: border-box;
    margin: 0rem;
    min-inline-size: var(--target-size-min);
    block-size: 100%;
    min-block-size: var(--control-height-md);
    padding-inline: var(--space-xs);
    border: none;
    border-radius: var(--radius-sm);
    background-color: transparent;
    color: var(--color-text-secondary);
    cursor: default;
    transition:
      background-color var(--duration-fast) var(--easing-standard),
      color var(--duration-fast) var(--easing-standard);
  }

  .dh-combobox__trigger:hover,
  .dh-combobox__clear:hover {
    background-color: var(--color-primary-subtle);
    color: var(--color-on-primary-subtle);
  }

  .dh-combobox__chevron {
    inline-size: var(--space-xs);
    block-size: var(--space-xs);
    border-inline-end: var(--border-width-strong) solid var(--color-text-secondary);
    border-block-end: var(--border-width-strong) solid var(--color-text-secondary);
    rotate: 45deg;
  }

  .dh-combobox__clear-glyph {
    font-family: var(--font-family-body);
    font-size: var(--font-size-body-md);
    line-height: var(--line-height-body-md);
  }

  .dh-combobox__spinner {
    box-sizing: border-box;
    inline-size: var(--space-md);
    block-size: var(--space-md);
    border-width: var(--border-width-strong);
    border-style: solid;
    border-color: var(--color-border-subtle);
    border-block-start-color: var(--color-primary);
    border-radius: var(--radius-full);
    animation: dh-combobox-spin var(--duration-slow) linear infinite;
  }

  /* --- the floating listbox ------------------------------------------------------ */

  [data-part="positioner"]:where([data-scope="combobox"]) {
    z-index: 1;
    inline-size: 100%;
  }

  [data-part="content"]:where([data-scope="combobox"]) {
    box-sizing: border-box;
    inline-size: 100%;
    /* 256px of scrollable option surface, derived from the grid rather than authored. */
    max-block-size: calc(var(--space-xxxl) * 4);
    overflow-y: auto;
    padding-block: var(--space-xxs);
    border-width: var(--border-width-hairline);
    border-style: solid;
    border-color: var(--color-border-subtle);
    border-radius: var(--radius-sm);
    background-color: var(--color-surface-raised);
    /* Elevation is never shadow alone: the hairline border above survives dark mode. */
    box-shadow: var(--elevation-1);
    opacity: 0;
    /* Enter on the entry curve, leave on the exit curve (RESEARCH.md §6.2). */
    transition: opacity var(--duration-moderate) var(--easing-entry);
  }

  [data-part="content"][data-state="open"]:where([data-scope="combobox"]) {
    opacity: 1;
  }

  [data-part="content"][data-state="closed"]:where([data-scope="combobox"]) {
    transition-timing-function: var(--easing-exit);
  }

  [data-part="list"]:where([data-scope="combobox"]) {
    margin: 0rem;
    padding: 0rem;
    list-style: none;
  }

  [data-part="option"]:where([data-scope="combobox"]) {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    padding-block: var(--space-xxs);
    padding-inline: var(--input-padding-inline);
    border-inline-start: var(--border-width-strong) solid transparent;
    border-radius: var(--radius-sm);
    color: var(--color-text-primary);
    font-size: var(--font-size-body-md);
    line-height: var(--line-height-body-md);
    cursor: default;
    transition:
      background-color var(--duration-fast) var(--easing-standard),
      color var(--duration-fast) var(--easing-standard);
  }

  [data-part="option"][data-highlighted]:where([data-scope="combobox"]) {
    background-color: var(--color-primary-subtle);
    color: var(--color-on-primary-subtle);
  }

  /* The committed option is heavier and carries the selected seam — never colour alone. */
  [data-part="option"][aria-selected="true"]:where([data-scope="combobox"]) {
    border-inline-start-color: var(--color-border-selected);
    font-weight: var(--font-weight-label-caps);
  }

  [data-part="option"][aria-disabled="true"]:where([data-scope="combobox"]) {
    color: var(--color-text-secondary);
    cursor: default;
    opacity: 0.55;
  }

  .dh-combobox__loading,
  .dh-combobox__empty {
    padding-block: var(--space-xs);
    padding-inline: var(--input-padding-inline);
    font-size: var(--font-size-body-sm);
    line-height: var(--line-height-body-sm);
    color: var(--color-text-secondary);
  }

  .dh-combobox__loading {
    border-block-end: var(--border-width-hairline) solid var(--color-border-subtle);
    font-style: italic;
  }

  @keyframes dh-combobox-spin {
    from {
      rotate: 0turn;
    }

    to {
      rotate: 1turn;
    }
  }
}

/**
 * Class-name helpers for the styled layer.
 *
 * The styled layer's only DOM contribution is *class names*: every structural and
 * state signal (`data-scope`, `data-part`, `data-open`, `data-disabled`, `aria-*`)
 * is owned by `@designharness/primitives` and is never re-implemented, renamed or
 * overridden here (TOKEN-API.md §5). Component CSS is authored against those
 * attributes plus the `dh-<component>` block / `dh-<component>--<variant>` modifier
 * classes produced by these helpers.
 */

/** Any value that a class list may legitimately contain. */
export type ClassValue = string | false | null | undefined;

/** Join a class list, dropping empty entries and collapsing to a single string. */
export function cx(...values: readonly ClassValue[]): string {
  const parts: string[] = [];
  for (const value of values) {
    if (typeof value === 'string' && value.length > 0) parts.push(value);
  }
  return parts.join(' ');
}

/**
 * BEM-ish modifier builder: `modifier('dh-button', 'primary')` → `dh-button--primary`.
 * A `false`/`undefined` modifier yields `undefined` so it can be passed to `cx` directly.
 */
export function modifier(block: string, value: string | false | null | undefined): string | undefined {
  if (!value) return undefined;
  return `${block}--${value}`;
}

/**
 * Element builder: `element('dh-button', 'spinner')` → `dh-button__spinner`.
 * Elements are markup *the styled layer itself renders* — never anatomy parts.
 */
export function element(block: string, name: string): string {
  return `${block}__${name}`;
}

/**
 * Merge a consumer `className` after the styled-layer classes so a host app can add
 * utility classes without ever losing the tokenized base (source order, no `!important`).
 */
export function withConsumerClass(styled: string, className: ClassValue): string {
  return cx(styled, className);
}
